    "content": "以尼姆鲁德西北宫多房间的护壁雕刻与门道为范围，依据大都会博物馆对亚述雕塑展厅和原宫殿的整体解释，比较重复护佑人物、王权叙事及门口神兽。展厅是代表性组合，不是完整宫殿复原，现存石雕也多已失去古代彩色。",
