    "url": "https://www.metmuseum.org/met-publications/the-metropolitan-museum-of-art-bulletin-v-24-no-4-december-1965",
    "content": "以大都会博物馆对埃及家具的专题研究为共同结构依据，选取新王国早期至第十八王朝座具原物比较木框、连接、编织座面及便携形式。木材与修复状态逐件核对，不把墓葬传世精品直接当作每个古埃及家庭的全部生活用品。",
    "use": "先画木框和接点，再加编织座面；区分固定腿与折叠交叉腿、原件与补件，摆放人物时注意低座高度与背部支撑。",
