    "use": "画工坊先分刻版与印刷工位，保留凸线、刷、湿纸和马连的操作关系；彩印另安排定位切口。",
    "caution": "研究范围以传统浮世绘工坊为主，不涵盖所有日本出版方式或现代橡胶版。",
