    "id": "topic-west-arch-british-worker-housing",
    "module": "architecture",
    "category": "houses",
    "name": "19—20世纪英国工薪住宅：合院共用设施与市营花园住房",
    "region": "英国",
    "period": "1802—1967年案例与住房转变",
    "kind": "中文专题",
    "entryType": "专题考据",
    "focus": "专题考据",
    "url": "https://www.nationaltrust.org.uk/visit/birmingham-west-midlands/birmingham-back-to-backs/history-of-birmingham-back-to-backs",
    "content": "以伯明翰Court 15背靠背/盲背住宅群和1920年代伦敦Becontree市营住宅作地域与时期对照，研究住房怎样安排家务、谋生、院子与卫生设施。前者多熟练工和手艺人，后者最初面向收入较稳的工薪家庭，不能代表最贫困者或全英国同一种住房。",
    "use": "画旧合院先安排共同院口、厕所洗衣房与工作入口；画市营住宅再加入各户花园和室内卫生设施，用活动差异表达住房条件。",
    "caution": "比较的两地与住户收入不同，不能说所有工人都从内院房搬进花园住宅；Court 15直到1967才结束居住。",
