        {
          "title": "中央柜台连接成人与儿童区",
          "text": "1908后Bertram加强审图，1911发表实用布局建议；常采用的一型把成人阅览区和儿童区分两侧，柜台在中间面向入口，便于服务与观察。不是每馆必须照搬同一平面。",
          "refs": [
            "cl"
          ]
        },
        {
          "title": "高窗与台阶和楼层安排有关",
          "text": "较高的主要读者层及半地下辅助层使公共室内获得采光与通风，也造成常见的入馆台阶；不能把台阶仅解释为象征向知识攀登。",
          "refs": [
            "cl"
          ]
        },
        {
          "title": "部分馆兼作社区文化空间",
          "text": "Connellsville馆1903开放，二层礼堂举办音乐活动；HABS记录同时说明礼堂使用受馆方规则限制，社区用途不等于所有政治或宗教活动自动获准。",
          "refs": [
            "cf",
            "ch"
          ]
        }
