    "content": "研究18世纪后半叶英属北美家庭围绕柴火炉膛配套使用的烹饪器具，以波士顿无爵位的银匠Paul Revere家庭为生活场景，再用馆藏铁锅核对悬挂和炉床使用。这里的平民指没有贵族爵位的家庭，不等于赤贫；城市工匠家庭、农村家庭及种植园厨房的劳动条件不能合并。",
    "use": "画面先安排炉膛、侧边砖炉和工作台，再选煮、烤、备料三组器具。普通家庭锅具应有重量感；吊锅画提梁和挂钩，立锅画三足。不要依据博物馆局部照片虚构看不见的炉架。",
    "caution": "所述平民家庭以有财产的城市工匠为主，不能当作所有贫困家庭、原住民家庭或奴役劳动者家庭的统一配置。",
    "find": "18世纪后半叶北美平民家庭厨房：柴火、煮锅、炉边烘烤与工作台 西方生活",
    "collect": "一类器具的共同特征、分型、使用关系、家庭身份与机构原图",
