    "name": "1763—1969年巴黎市场：粮仓、交易大厅与装卸空间",
    "region": "法国（巴黎）",
    "period": "1763—1969年；粮食大厅与中央市场的分期比较",
    "kind": "中文专题",
    "entryType": "专题考据",
