          "title": "家庭成员围绕节庆核心聚集",
          "text": "德国家庭圣诞的形成与私生活和家庭教育受到重视有关；馆方介绍围树聚集、儿童朗诵或家庭音乐及馈赠，人物应有明确代际关系和活动位置。",
