    "region": "法国／英国",
    "period": "1828—1926年；法国仪式类型与英国消费资料比较",
    "kind": "中文专题",
    "entryType": "专题考据",
    "focus": "专题考据",
    "url": "https://histoire-image.org/etudes/mariage-ses-pratiques-xixe-siecle",
    "content": "以19世纪法国市民及乡村婚礼为主要范围，比较民事登记、宗教祝福、家族庆祝和婚礼摄影，并用英国博物馆资料解释白婚纱经印刷媒体传到法国的视觉理想及20世纪成衣变化。城乡和阶层会改变人数、花费与仪式内容，不能把这一比较写成全部欧洲婚礼的统一流程。",
    "use": "画婚礼前先选地区、年代和阶段：市政厅、教堂、宴席、乡村游行或照相馆。让见证人、亲属、乐师或摄影师各有任务，并避免把乡村地方服装全部换成贵族宫廷礼服。",
    "caution": "两篇法国机构研究的历史绘画与版画有艺术选择和理想化；不能把某幅作品的人数、衣着与仪式细节当作法国所有人的统计。",
