          "title": "仪式之外还有家庭与宾客",
          "text": "婚礼不是只有一对新人面对主持者；市民资料展示家人、见证人、宴席和舞会，乡村图像则出现全村观看与集体欢庆，群体参与构成事件的重要部分。",
