      "drawing": "先画盒的开合方向和每条槽格，再按长短放剪、刀、镊与穿带针。要表现中产商品可参考搪瓷铜型，别自动升级成满镶宝石的机关匣；外销奢侈型必须与英国日常消费者场景区分。",
