    "use": "先选择手摇或脚踏，完整画出动力来源；脚踏式人物脚下要留踏板和连杆，手摇式不能把两手都长时间画在远处。核对针板、压脚、线轴和带轮位置；单线链式机不要随意补上通用梭子。",
    "caution": "家庭使用者收入和有无机器差异明显；本题介绍可选机型，既不声称家家普及，也不把有机器的家庭自动称为贵族或富豪。",
    "find": "1860—1930年美国家庭缝纫机：手摇、脚踏、柜桌与针迹分型 西方生活续编 西方生活",
